#include <iostream>

struct Base {
  virtual void show(int) { std::cout << "B-int"; }
  virtual void show(double) { std::cout << "B-double"; }
};
struct Derived : Base {
  void show(int) override { std::cout << "D-int"; }
  void show(short) { std::cout << "D-short"; }
};

int main() {
  Derived object;
  Base& base = object;
  short value = 1;
  base.show(value);
}
